using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Threading;
using System.Collections.Generic;
using DogSC.Windows;

namespace DogSC.Replica {
 static class EffectsTests {
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  public static string Prepare(string folder){Directory.CreateDirectory(folder);string chart=Path.Combine(folder,"chart.png"),sticker=Path.Combine(folder,"sticker.png");using(var image=new Bitmap(1280,720))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(239,247,249));using(var font=new Font("Segoe UI",30))g.DrawString("DogSC · Windows effects",font,Brushes.DarkSlateGray,70,70);using(var font=new Font("Segoe UI",18))g.DrawString("Independent cursor / image sticker / local softening",font,Brushes.SlateGray,72,140);for(int x=80;x<1200;x+=4)g.FillRectangle(x%8==0?Brushes.White:Brushes.DarkSlateGray,x,250,4,350);image.Save(chart,ImageFormat.Png);}
   using(var image=new Bitmap(280,120,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=StudioRenderer.Round(new RectangleF(15,15,250,90),24))using(var fill=new SolidBrush(Color.FromArgb(245,92,88)))g.FillPath(fill,shape);using(var font=new Font("Segoe UI",28,FontStyle.Bold))g.DrawString("Hello!",font,Brushes.White,60,36);image.Save(sticker,ImageFormat.Png);}
   string source=Path.Combine(folder,"source.mkv");StudioMedia.Run("-v error -y -loop 1 -i "+Media.Q(chart)+" -t 2.2 -r 30 -c:v ffv1 "+Media.Q(source),CancellationToken.None);return source;
  }
  static Bitmap Render(Bitmap source,EditDocument doc,double time){var image=new Bitmap(1280,720,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(image))using(var motion=new MotionEvaluator(doc)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.SmoothingMode=SmoothingMode.AntiAlias;StudioRenderer.Draw(g,source,doc,motion,time,1280,720,null,image);}return image;}
  static double Contrast(Bitmap image,Rectangle area){double sum=0,squares=0,count=0;for(int y=area.Top;y<area.Bottom;y+=3)for(int x=area.Left;x<area.Right;x++){double value=image.GetPixel(x,y).R;sum+=value;squares+=value*value;count++;}return Math.Sqrt(Math.Max(0,squares/count-Math.Pow(sum/count,2)));}
  static int Difference(Bitmap a,Bitmap b){int changed=0;for(int y=0;y<a.Height;y+=3)for(int x=0;x<a.Width;x+=3){var p=a.GetPixel(x,y);var q=b.GetPixel(x,y);if(Math.Abs(p.R-q.R)+Math.Abs(p.G-q.G)+Math.Abs(p.B-q.B)>30)changed++;}return changed;}
  public static void Run(string folder){string source=Prepare(folder);var doc=StudioMedia.Import(source);doc.Style.Padding=0;doc.Style.Frame="none";doc.Style.Radius=0;doc.Style.Shadow=0;doc.Style.Opening=0;doc.Style.Follow=false;doc.Style.AutoZoom=false;doc.IndependentCursor=true;doc.Cursor.Smoothing=0;doc.Cursor.ClickEffect="none";for(int i=0;i<=44;i++)doc.Pointer.Add(new PointerSample {Time=i*.05,X=.1+i*.008,Y=.25,CursorKind=i>20?"ibeam":"arrow"});
   var legacy=EditDocument.Serializer().Deserialize<Dictionary<string,object>>(doc.Serialize());legacy.Remove("Cursor");legacy.Remove("IndependentCursor");legacy.Remove("Overlays");var old=EditDocument.Deserialize(EditDocument.Serializer().Serialize(legacy));old.Validate();Check(!old.IndependentCursor&&old.Cursor!=null&&old.Overlays.Count==0,"Legacy project migration");
   var cut=EditDocument.Deserialize(doc.Serialize());cut.Cuts=new List<Cut>{new Cut {Start=1,End=2,Speed=2},new Cut {Start=0,End=1}};using(var motion=new MotionEvaluator(cut)){Check(Math.Abs(motion.CursorAt(.25).X-.34)<.003,"Pointer was not mapped through cuts/reorder/speed");Check(Math.Abs(motion.CursorAt(.75).X-.14)<.003,"Pointer crossed a cut incorrectly");var a=motion.CursorAt(.25);motion.CursorAt(.7);Check(Math.Abs(a.X-motion.CursorAt(.25).X)<1e-8,"Cursor random seek is not deterministic");}
   var idle=EditDocument.Deserialize(doc.Serialize());foreach(var p in idle.Pointer){p.X=.5;p.Y=.5;}idle.Cursor.HideWhenIdle=true;using(var motion=new MotionEvaluator(idle)){Check(motion.CursorAt(.3).Visible&&!motion.CursorAt(1.8).Visible,"Idle cursor hide");}doc.Cursor.TimeOffset=.2;using(var motion=new MotionEvaluator(doc)){Check(Math.Abs(motion.CursorAt(.7).X-.18)<.003,"Independent cursor time offset");}doc.Cursor.TimeOffset=0;
   using(var stream=new MemoryStream(StudioMedia.Frame(source,.5,1280)))using(var frame=new Bitmap(stream)){
    doc.Cursor.Asset="hidden";using(var baseline=Render(frame,doc,.5)){foreach(var style in new[]{"arrow","hand","crosshair","ibeam","openHand","closedHand","notAllowed","dot"}){doc.Cursor.Asset=style;using(var visible=Render(frame,doc,.5))Check(Difference(baseline,visible)>2,"Cursor style missing: "+style);}doc.Cursor.Asset="arrow";var click=doc.Pointer[8];using(var arrow=Render(frame,doc,.5)){click.Click=true;foreach(var style in new[]{"ripple","glow","pulse","burst"}){doc.Cursor.ClickEffect=style;using(var visible=Render(frame,doc,.5))Check(Difference(arrow,visible)>2,"Click feedback missing: "+style);}}doc.Cursor.Asset="hidden";using(var hidden=Render(frame,doc,.5))Check(Difference(baseline,hidden)==0,"Hidden cursor still renders click feedback");doc.Cursor.ClickEffect="none";click.Click=false;
     var blur=new OverlayClip {Start=.2,End=1.8,X=.2,Y=.35,Width=.35,Height=.4,Intensity=.7};doc.Overlays.Add(blur);using(var softened=Render(frame,doc,.5)){Check(Contrast(softened,new Rectangle(330,300,250,130))<Contrast(baseline,new Rectangle(330,300,250,130))*.35,"Local softening did not blur detail");Check(softened.GetPixel(100,300).ToArgb()==baseline.GetPixel(100,300).ToArgb(),"Softening changed pixels outside selected area");softened.Save(Path.Combine(folder,"softening.png"));}using(var before=Render(frame,doc,.1))Check(Difference(baseline,before)==0,"Effect starts before timing");using(var after=Render(frame,doc,1.9))Check(Difference(baseline,after)==0,"Effect survives after timing");blur.Kind="spotlight";blur.Dimming=.5;using(var spotlight=Render(frame,doc,.5)){Check(spotlight.GetPixel(400,300).ToArgb()==baseline.GetPixel(400,300).ToArgb(),"Spotlight changed inside area");Check(spotlight.GetPixel(50,50).R<baseline.GetPixel(50,50).R*.65,"Spotlight did not dim outside");}doc.Overlays.Clear();
     var sticker=OverlayClip.Image(Path.Combine(folder,"sticker.png"),.2,1.8);sticker.Shadow=0;sticker.Corner=0;sticker.Animation="none";sticker.BackdropBlur=0;sticker.Width=.25;sticker.X=sticker.Y=.5;doc.Overlays.Add(sticker);using(var pasted=Render(frame,doc,.5)){var red=pasted.GetPixel(515,355);Check(red.R>200&&red.G<130,"Embedded transparent sticker did not render");Check(pasted.GetPixel(485,295).ToArgb()==baseline.GetPixel(485,295).ToArgb(),"PNG transparent padding became opaque");pasted.Save(Path.Combine(folder,"sticker.png.preview.png"));}
     var second=EditDocument.Serializer().Deserialize<OverlayClip>(EditDocument.Serializer().Serialize(sticker));second.Id=Guid.NewGuid().ToString("N");using(var image=new Bitmap(100,100))using(var g=Graphics.FromImage(image))using(var bytes=new MemoryStream()){g.Clear(Color.Blue);image.Save(bytes,ImageFormat.Png);second.ImageData=Convert.ToBase64String(bytes.ToArray());second.ImageWidth=second.ImageHeight=100;}doc.Overlays.Add(second);using(var layered=Render(frame,doc,.5))Check(layered.GetPixel(640,360).B>200,"Sticker layer order");doc.Overlays.Remove(second);
     sticker.HideScreen=true;using(var hidden=Render(frame,doc,.5))Check(hidden.GetPixel(100,300).ToArgb()!=baseline.GetPixel(100,300).ToArgb(),"Sticker screen suppression");sticker.HideScreen=false;sticker.BackdropBlur=20;using(var backdrop=Render(frame,doc,.5))Check(Contrast(backdrop,new Rectangle(100,300,200,130))<Contrast(baseline,new Rectangle(100,300,200,130))*.4,"Sticker backdrop blur");sticker.BackdropBlur=0;sticker.Rotation=30;using(var rotated=Render(frame,doc,.5))Check(Difference(baseline,rotated)>100,"Sticker rotation");sticker.Rotation=0;
     sticker.Animation="pop";sticker.Curve="swift";Check(EffectRenderer.StickerVisibility(sticker,.2)<.001&&EffectRenderer.StickerVisibility(sticker,1)>.99,"Sticker entry animation");sticker.Animation="none";doc.Cursor.Asset="arrow";doc.Overlays.Add(blur);blur.Kind="blur";doc.Validate();string project=Path.Combine(folder,"effects.dogscwin");doc.Save(project);File.Delete(Path.Combine(folder,"sticker.png"));var reopened=EditDocument.Deserialize(File.ReadAllText(project));reopened.Validate();using(var original=Render(frame,doc,1))using(var restored=Render(frame,reopened,1))Check(Difference(original,restored)==0,"Project did not preserve assets/effects independently of source image");
     string output=Path.Combine(folder,"export.mp4");StudioRenderer.Export(reopened,output,720,30,(v,s)=>{},CancellationToken.None);var exported=StudioMedia.Import(output);Check(exported.Width==1280&&exported.Height==720,"Export resolution");using(var bytes=new MemoryStream(StudioMedia.Frame(output,1,1280)))using(var actual=new Bitmap(bytes)){var red=actual.GetPixel(515,355);Check(red.R>180&&red.G<150,"Sticker missing from exported video");Check(Contrast(actual,new Rectangle(330,300,120,130))<Contrast(baseline,new Rectangle(330,300,120,130))*.4,"Softening missing from exported video");}
    }
   }
   File.WriteAllText(Path.Combine(folder,"core-results.txt"),"PASS: legacy migration; cursor styles, clicks, idle hide, timing, cuts/reorder/speed; timed local blur/spotlight; transparent embedded stickers, layers, rotation, backdrop/suppression, animations; save/reopen after image removal; actual MP4 export.\n");
  }
 }
}
